/** An inline icon. Decorative unless a label is given. */
export function icon(name, { label = '', className = 'icon' } = {}) {
  const paths = PATHS[name];
  if (!paths) throw new Error(`Unknown icon: ${name}`);
  const a11y = label ? `role="img" aria-label="${label.replace(/[&<>"']/g, c => ({ '&': '&amp;', '<': '&lt;', '>': '&gt;', '"': '&quot;', "'": '&#39;' }[c]))}"` : 'aria-hidden="true"';
  return `<svg class="${className}" viewBox="0 0 256 256" fill="currentColor" focusable="false" ${a11y}>${paths}</svg>`;
}
